	tw.local.documentSectionVisibility = "NONE";
}

var breadcrumbText = null;
if (window.location.href.indexOf('breadcrumbText=') != -1) {
	breadcrumbText = window.location.href.substring(window.location.href.indexOf('breadcrumbText=')+15);
	if (breadcrumbText.indexOf('&') != -1) {
		breadcrumbText = breadcrumbText.substring(0,breadcrumbText.indexOf('&'));
	}
	if (breadcrumbText.indexOf('#') != -1) {
		breadcrumbText = breadcrumbText.substring(0,breadcrumbText.indexOf('#'));
	}
}
 
var _debug = function(){};
// enable following line to log into browser console
//var _debug = console.log;

try {
	// check for breadcrumb
	tw.local.breadcrumbs = [];
	if (breadcrumbText) {
		tw.local.breadcrumbs.push({
			name: decodeURI(breadcrumbText),
			value: '{"value":"back","navigationDestination":"BACK"}'
		});
	}
 
} catch (err) {
	console.log("Error within Instance Details initialization: "+err);
}


