	// Calculate if there are any relevant incoming changes

	// There are unsaved changes . This can be detected by calling tw.system.coachUtils.hasLocallyChangedInputVars(). Here, however, this variable is
	// set by the Data Section coach view when it detects that a child view's data binding has changed.
	if(tw.local.unsavedLocalChanges === true || tw.system.coachUtils.hasLocallyChangedInputVars()){
		
		if(!tw.local.unsavedLocalChanges)
			tw.local.unsavedLocalChanges = true;
			
		// Call the helper function to update the incoming and local changes.
		checkIncomingChanges(tw.local, tw.system.coachUtils.getLocallyChangedVars(), tw.system.dataChangeUtils.getIncomingVars())		 
		
	} else if(tw.system.coachUtils.getLocallyChangedVars().length > 0) { // No pending changes to be merged, or local changes
	
		// Apply incoming changes to the local variables.
		tw.system.dataChangeUtils.applyAllIncomingVars();
		tw.local.incomingChangesMerged = true; // Signal that changes were applied automatically. The Data Section can listen and pop up a notification.
	 
	}

}); "]}},{"targetRef":"2025.9dbefb88-4450-4f75-8087-03f63e037734","extensionElements":{"linkVisualInfo":[{"sourcePortLocation":"rightCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":false,"showLabel":false}]},"name":"To Collect change information","declaredType":"sequenceFlow","id":"2027.96aebb04-09ac-4c22-ac8f-6adfd9c830c2","sourceRef":"2025.6f2fad4c-f487-4c12-9578-14c9766e3c3d"},{"targetRef":"2025.8c562ac8-2260-469b-a1c5-54e6ddf7359e","extensionElements":{"linkVisualInfo":[{"sourcePortLocation":"rightCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":false,"showLabel":false}]},"name":"To Stay on page","declaredType":"sequenceFlow","id":"2027.6ef6caec-33ee-4bce-b104-e257be3e8334","sourceRef":"2025.9dbefb88-4450-4f75-8087-03f63e037734"}],"startQuantity":1,"extensionElements":{"nodeVisualInfo":[{"width":95,"x":51,"y":463,"declaredType":"TNodeVisualInfo","height":70}]},"name":"Data Change","triggeredByEvent":true,"isForCompensation":false,"completionQuantity":1,"declaredType":"subProcess","id":"2025.3b26091c-110e-47bd-81eb-3cc8d05367ba"},{"targetRef":"2025.798e9a92-2ab1-4f95-a7ea-a55772bc218f","extensionElements":{"linkVisualInfo":[{"sourcePortLocation":"topCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":false,"showLabel":true}]},"name":"Yes","declaredType":"sequenceFlow","id":"2027.2b65bd61-7379-447e-b06f-96bd2174c619","sourceRef":"2025.ca7df8f2-790f-45c0-b4e5-2ab0008279a8"},{"startQuantity":1,"outgoing":["2027.2af86bea-d3b1-42b3-b5ce-a29a66a1a9c7"],"incoming":["2027.7e640d6c-3a9a-48d5-8c21-eaba8ae03c0a"],"default":"2027.2af86bea-d3b1-42b3-b5ce-a29a66a1a9c7","extensionElements":{"nodeVisualInfo":[{"width":95,"x":523,"y":103,"declaredType":"TNodeVisualInfo","height":70}]},"name":"Init Data Change Support","isForCompensation":false,"completionQuantity":1,"declaredType":"scriptTask","id":"2025.3d0505be-e6c6-4d62-9eb0-0cc42cb558d0","scriptFormat":"text/x-javascript","script":{"content":["require([tw.local.helperScriptURL], function() { // Load the helper functions

	// Initialize variables that support data change syncrhonization. 
	
	// This can only be done once the URL for the helper functions is returned by the 
	// Server Sice Init Data. Since this is can also be invoked as part of auto refresh the initialization
	// should only happen if the variables are undefined.
	
	if(tw.local.originalInput == undefined && tw.local.localChanges == undefined && tw.local.incomingChanges == undefined){
		initializeDataSyncronizationVariables(tw.local); // Intialize variables
	}
	
}); 
