ns16:scriptTask.ns16:script:
tw.local.selectedInstanceId = tw.system.processInstance.id;
if (tw.system.processInstance.parentActivityId && (tw.system.processInstance.parentActivityId != null)) {
	tw.local.documentSectionVisibility = "NONE";
}

var breadcrumbText = null;
if (window.location.href.indexOf('breadcrumbText=') != -1)  {
	breadcrumbText = window.location.href.substring(window.location.href.indexOf('breadcrumbText=')+15);
	if (breadcrumbText.indexOf('&') != -1) {
		breadcrumbText = breadcrumbText.substring(0,breadcrumbText.indexOf('&'));
	}
	if (breadcrumbText.indexOf('#') != -1) {
		breadcrumbText = breadcrumbText.substring(0,breadcrumbText.indexOf('#'));
	}
}
                                
var _debug = function(){};
// enable following line to log into browser console
//var _debug = console.log;

try {
	// check for breadcrumb
	tw.local.breadcrumbs = [];
	if (breadcrumbText) {
		tw.local.breadcrumbs.push({
			name: decodeURI(breadcrumbText),
			value: '{"value":"back","navigationDestination":"BACK"}'
		});
	}
    
} catch (err) {
	console.log("Error within Instance Details initialization: "+err);
}

//  Check for validation errors in the instance data. For examle:
// if (tw.local.name == "" ) {
//    tw.system.coachValidation.addValidationError("tw.local.name", "Name must be specified");
// }

require([tw.local.helperScriptURL], function() { // Load the helper functions

	// The merge the server changes into the local variables based on the merge policy picked by the user.

	// Determine what type of merge the user requested
	var keepConflictingLocalChanges = false;
	if(tw.local.dataSectionBoundaryEventType === "KEEP_LOCAL")
		keepConflictingLocalChanges = true;
		
	merge(tw.local, keepConflictingLocalChanges); // Reset variables
	          
});

require([tw.local.helperScriptURL], function() { // Load the helper functions

	// The local variables have been refreshed with the latest changes from the server,
	// or the instance UI has been saved.  There are no pending changes.  Reset merge data.
		
	resetDataSyncronizationVariables(tw.local); // Reset variables
	          
});

require([tw.local.helperScriptURL], function() { // Load the helper functions
	
	// Calculate if there are any relevant incoming changes

	// There are unsaved changes .  This can be detected by calling tw.system.coachUtils.hasLocallyChangedInputVars().  Here, however, this variable is
	// set by the Data Section coach view when it detects that a child view's data binding has changed.
	if(tw.local.unsavedLocalChanges ===  true || tw.system.coachUtils.hasLocallyChangedInputVars()){
		
		if(!tw.local.unsavedLocalChanges)
			tw.local.unsavedLocalChanges = true;
			
		// Call the helper function to update the incoming and local changes.
		checkIncomingChanges(tw.local, tw.system.coachUtils.getLocallyChangedVars(),  tw.system.dataChangeUtils.getIncomingVars())		          
		
	} else if(tw.system.coachUtils.getLocallyChangedVars().length > 0) { // No pending changes to be merged, or local changes
	
		// Apply incoming changes to the local variables.
		tw.system.dataChangeUtils.applyAllIncomingVars();
		tw.local.incomingChangesMerged = true;  // Signal that changes were applied automatically.  The Data Section can listen and pop up a notification.
	 
	}

});

require([tw.local.helperScriptURL], function() { // Load the helper functions

	// Initialize variables that support data change syncrhonization.  
	
	// This can only be done once the URL for the helper functions is returned by the 
	// Server Sice Init Data.  Since this is can also be invoked as part of auto refresh the initialization
	// should only happen if the variables are undefined.
	
	if(tw.local.originalInput == undefined && tw.local.localChanges == undefined && tw.local.incomingChanges == undefined){
		initializeDataSyncronizationVariables(tw.local); // Intialize variables
	}
	
});

